        source: 'validator'
      });
      continue;
    }
    if (PLACEHOLDER.test(body)) {
      findings.push({
        checkId: check.id,
        severity: 'block',
        message: `"${check.title}" contains placeholder text (TBD/TODO). Answer it concretely.`,
        source: 'validator'
      });
    }
    const emptyFields = lines.filter((_, i) => unanswered[i]);
    for (const line of emptyFields) {
      findings.push({
        checkId: check.id,
        severity: 'block',
        message: `Unanswered field in "${check.title}": ${line.trim()}`,
        source: 'validator'
      });
    }
    for (const line of lines.filter((l) => NEEDS_HUMAN_INPUT.test(l))) {
      findings.push({
        checkId: check.id,
        severity: 'block',
        message: `Unresolved NEEDS HUMAN INPUT in "${check.title}": ${humanInputQuestion(line)}`,
        source: 'validator'
      });
    }
    if (check.expectsNumbers && !/\d/.test(answered)) {
      findings.push({
        checkId: check.id,
        severity: 'warn',
        message: `"${check.title}" has no numeric threshold. A check that cannot fail is not a check.`,
        source: 'validator'
      });
    }

    if (check.id === 'risk-tier') {
      tier = extractTier(body);
      if (!tier) {
        findings.push({
          checkId: check.id,
          severity: 'block',
          message: 'Risk tier must be one of: prohibited, high, limited, minimal.',
          source: 'validator'
        });
      } else if (tier === 'prohibited') {
        findings.push({
          checkId: check.id,
          severity: 'block',
          message: 'Risk tier is "prohibited" - this feature must not be built.',
          source: 'validator'
        });
      } else if (tier === 'high') {
        const signoff = signoffValue(lines, unanswered);
        if (!signoff || /not\s+required/i.test(signoff)) {
          findings.push({
            checkId: check.id,
            severity: 'block',
            message: 'High-risk tier requires a named human sign-off (name + date) in the spec.',
            source: 'validator'
          });
        }
      }
    }
  }

  return { verdict: verdictFrom(findings), tier, findings, gateSection };
}

import {
  Finding,
  GATE_CHECKS,
  GATE_HEADING,
  GateResult,
  RISK_TIERS,
  RiskTier,
  verdictFrom
} from './schema.js';

const PLACEHOLDER = /\b(TBD|TODO|FIXME|XXX)\b|\bfill\s+(this\s+)?in\b/i;
/** A template field line whose value was never filled in, e.g. `- **Retention**:` */
const EMPTY_FIELD = /^\s*[-*]\s*\*\*[^*]+\*\*.*:\s*$/;
/** A bold-labelled list item: `- **Retention**: 30 days` or `- **Retention:** 30 days`. */
const FIELD_LINE = /^\s*[-*]\s*\*\*(.+?)\*\*(.*)$/;
/** The marker `frai-gate draft` leaves where only a human can answer. */
const NEEDS_HUMAN_INPUT = /NEEDS\s+HUMAN\s+INPUT/;

interface Section {
  heading: string;
  body: string;
}

interface Field {
  label: string;
  /** The value written on the field line itself (may be empty). */
  inline: string;
}

function indentOf(line: string): number {
  const lead = line.match(/^[ \t]*/)?.[0] ?? '';
  return lead.replace(/\t/g, '    ').length;
}

/** Parses a field line in either label style; null when the line is not a `label: value` field. */
function parseField(line: string): Field | null {
  const m = line.match(FIELD_LINE);
  if (!m) return null;
  const label = m[1].trim();
  if (label.endsWith(':')) {
    return { label: label.slice(0, -1).trim(), inline: m[2].trim() };
  }
  // Skip a hint like "(high tier: name + date; otherwise "not required (tier below high)")"
  // so a colon inside it is not mistaken for the label's colon.
  let rest = m[2].trimStart();
  if (rest.startsWith('(')) {
    let depth = 0;
    let i = 0;
    for (; i < rest.length; i += 1) {
      if (rest[i] === '(') depth += 1;
      else if (rest[i] === ')') depth -= 1;
      if (depth === 0) break;
    }
    rest = rest.slice(i + 1).trimStart();
  }
  if (!rest.startsWith(':')) return null;
  return { label, inline: rest.slice(1).trim() };
}

/**
 * Index range [start, end) of the lines nested under line `index`: every following line indented
 * deeper than it, blank lines included, until a non-blank line at the same or a shallower indent.
 */
function childRange(lines: string[], index: number): [number, number] {
  const indent = indentOf(lines[index]);
  let end = index + 1;
  for (let j = index + 1; j < lines.length; j += 1) {
    if (!lines[j].trim()) continue;
    if (indentOf(lines[j]) <= indent) break;
    end = j + 1;
  }
  return [index + 1, end];
}

/**
 * Flags the field lines that were never answered: nothing after the label on the line, and
 * nothing but blank lines or other unanswered fields indented beneath it.
 */
function unansweredLines(lines: string[]): boolean[] {
  const unanswered = lines.map(() => false);
  // Walk backwards so nested fields are resolved before the field that contains them.
  for (let i = lines.length - 1; i >= 0; i -= 1) {
    const field = parseField(lines[i]);
    const emptyInline = EMPTY_FIELD.test(lines[i]) || (field !== null && field.inline === '');
    if (!emptyInline) continue;
    const [start, end] = childRange(lines, i);
    let answered = false;
    for (let j = start; j < end; j += 1) {
      if (lines[j].trim() && !unanswered[j]) {
        answered = true;
        break;
      }
    }
    unanswered[i] = !answered;
  }
  return unanswered;
}

/** The value of the field on line `index`: written on the line itself, or else on the lines nested below. */
function fieldValue(lines: string[], index: number): string {
  const inline = parseField(lines[index])?.inline ?? '';
  if (inline) return inline;
  const [start, end] = childRange(lines, index);
  return lines.slice(start, end).join('\n').trim();
}

function stripComments(markdown: string): string {
  return markdown.replace(/<!--[\s\S]*?-->/g, '');
}

/** Extracts the Responsible AI Gate section: from its heading to the next heading of the same or higher level. */
export function extractGateSection(markdown: string): string | null {
  const lines = markdown.split(/\r?\n/);
  let start = -1;
  let level = 0;
  for (let i = 0; i < lines.length; i += 1) {
    const m = lines[i].match(/^(#{1,6})\s+(.*)$/);
    if (m && GATE_HEADING.test(m[2])) {
      start = i;
      level = m[1].length;
      break;
    }
  }
  if (start === -1) return null;
  let end = lines.length;
  for (let i = start + 1; i < lines.length; i += 1) {
    const m = lines[i].match(/^(#{1,6})\s+/);
    if (m && m[1].length <= level) {
      end = i;
      break;
    }
  }
  return lines.slice(start, end).join('\n');
}

/** Splits the gate section into subsections keyed by their headings (any level deeper than the gate heading). */
function splitSubsections(gateSection: string): Section[] {
  const lines = gateSection.split(/\r?\n/);
  const gateLevel = lines[0].match(/^(#{1,6})/)?.[1]?.length ?? 1;
  const sections: Section[] = [];
  let current: Section | null = null;
  for (const line of lines.slice(1)) {
    const m = line.match(/^(#{1,6})\s+(.*)$/);
    if (m && m[1].length > gateLevel) {
      if (current) sections.push(current);
      current = { heading: m[2].trim(), body: '' };
    } else if (current) {
      current.body += `${line}\n`;
    }
  }
  if (current) sections.push(current);
  return sections;
}

function extractTier(body: string): RiskTier | null {
  // When an explicit "Tier" field line exists, it is authoritative - a fallback body
  // search would pick up incidental mentions like "(tier below high)" in the sign-off.
  const lines = body.split(/\r?\n/);
  const fieldIndex = lines.findIndex(
    (l) => /\*\*tier:?\*\*/i.test(l) || /^\s*[-*]\s*tier\b/i.test(l)
  );
  let haystacks = [body];
  if (fieldIndex !== -1) {
    const fieldLine = lines[fieldIndex];
    const field = parseField(fieldLine);
    haystacks = [fieldLine];
    if (field ? field.inline === '' : /:\s*$/.test(fieldLine)) {
      // The value sits on the indented lines below; if those mention several tiers,
      // the first of them is where the value is stated.
      const [start, end] = childRange(lines, fieldIndex);
      const nested = lines.slice(start, end);
      haystacks = [nested.join('\n'), nested.find((l) => l.trim()) ?? ''];
    }
  }
  for (const text of haystacks) {
    // Skip the template's enum hint "(prohibited / high / limited / minimal)".
    const cleaned = text.replace(/\((?:[^)]*\/){2,}[^)]*\)/g, '');
    const found = RISK_TIERS.filter((t) => new RegExp(`\\b${t}\\b`, 'i').test(cleaned));
    if (found.length === 1) return found[0];
    if (found.length > 1) {
      // Ambiguous mention; prefer the value after a colon on the field line.
      const afterColon = cleaned.split(':').slice(1).join(':');
      const inValue = RISK_TIERS.filter((t) => new RegExp(`\\b${t}\\b`, 'i').test(afterColon));
      if (inValue.length === 1) return inValue[0];
    }
  }
  return null;
}

function answeredText(lines: string[], unanswered: boolean[]): string {
  return lines
    .filter((_, i) => !unanswered[i])
    .join('\n')
    .trim();
}

function signoffValue(lines: string[], unanswered: boolean[]): string {
  const fieldIndex = lines.findIndex((l) => {
    const field = parseField(l);
    return field !== null && /sign[- ]?off/i.test(field.label);
  });
  if (fieldIndex !== -1) return fieldAnswer(lines, fieldIndex);
  const signoffLine = lines.find((l, i) => /sign[- ]?off/i.test(l) && !unanswered[i]);
  return signoffLine ? signoffLine.split(':').slice(1).join(':').trim() : '';
}

/** The question that follows a NEEDS HUMAN INPUT marker, shortened for a one-line finding. */
function humanInputQuestion(line: string): string {
  const m = line.match(NEEDS_HUMAN_INPUT);
  const after = m ? line.slice((m.index ?? 0) + m[0].length) : '';
  const question = after.replace(/^[\s:*_]+|[\s*_]+$/g, '') || line.trim();
  return question.length > 120 ? `${question.slice(0, 117)}...` : question;
}

export function validateSpec(markdown: string): GateResult {
  const findings: Finding[] = [];
  const clean = stripComments(markdown);
  const gateSection = extractGateSection(clean);

  if (!gateSection) {
    findings.push({
      checkId: 'structure',
      severity: 'block',
      message: 'No "## Responsible AI Gate" section found in the spec.',
      source: 'validator'
    });
    return { verdict: 'BLOCK', tier: null, findings, gateSection: null };
  }

  const subsections = splitSubsections(gateSection);
  let tier: RiskTier | null = null;

  for (const check of GATE_CHECKS) {
    const section = subsections.find((s) => check.headingPattern.test(s.heading));
    if (!section) {
      findings.push({
        checkId: check.id,
        severity: 'block',
        message: `Missing gate subsection: "${check.title}".`,
        source: 'validator'
      });
      continue;
    }

    const body = section.body;
    const lines = body.split(/\r?\n/);
    const unanswered = unansweredLines(lines);
    const answered = answeredText(lines, unanswered);

    if (!answered) {
      findings.push({
        checkId: check.id,
        severity: 'block',
        message: `"${check.title}" is present but empty.`,
        source: 'validator'
      });
      continue;
    }
    if (PLACEHOLDER.test(body)) {
      findings.push({
        checkId: check.id,
        severity: 'block',
        message: `"${check.title}" contains placeholder text (TBD/TODO). Answer it concretely.`,
        source: 'validator'
      });
    }
    const emptyFields = lines.filter((_, i) => unanswered[i]);
    for (const line of emptyFields) {
      findings.push({
        checkId: check.id,
        severity: 'block',
        message: `Unanswered field in "${check.title}": ${line.trim()}`,
        source: 'validator'
      });
    }
    for (const line of lines.filter((l) => NEEDS_HUMAN_INPUT.test(l))) {
      findings.push({
        checkId: check.id,
        severity: 'block',
        message: `Unresolved NEEDS HUMAN INPUT in "${check.title}": ${humanInputQuestion(line)}`,
        source: 'validator'
      });
    }
    if (check.expectsNumbers && !/\d/.test(answered)) {
      findings.push({
        checkId: check.id,
        severity: 'warn',
        message: `"${check.title}" has no numeric threshold. A check that cannot fail is not a check.`,
        source: 'validator'
      });
    }

    if (check.id === 'risk-tier') {
      tier = extractTier(body);
      if (!tier) {
        findings.push({
          checkId: check.id,
          severity: 'block',
          message: 'Risk tier must be one of: prohibited, high, limited, minimal.',
          source: 'validator'
        });
      } else if (tier === 'prohibited') {
        findings.push({
          checkId: check.id,
          severity: 'block',
          message: 'Risk tier is "prohibited" - this feature must not be built.',
          source: 'validator'
        });
      } else if (tier === 'high') {
        const signoff = signoffValue(lines, unanswered);
        if (!signoff || /not\s+required/i.test(signoff)) {
          findings.push({
            checkId: check.id,
            severity: 'block',
            message: 'High-risk tier requires a named human sign-off (name + date) in the spec.',
            source: 'validator'
          });
        }
      }
    }
  }

  return { verdict: verdictFrom(findings), tier, findings, gateSection };
}

